SELECT (server)::text AS server, (session_id)::text AS session_id, (transaction_id)::text AS transaction_id, NULL::text AS login_name, NULL::text AS host_name, NULL::text AS database_name, NULL::text AS status, NULL::text AS start_time, NULL::text AS command, NULL::text AS cpu_time, (duration_sec)::text AS total_elapsed_time, NULL::text AS query, entry_date, 'v_perf_sql_mem_001_rc11'::text AS source
